{"path": "/tmp/sv-c4cdb6d28c7d4bc5896cabf38b33df35/Components/Pages/Apply/StepIndicator.razor", "file_text": "@* Displays a horizontal step progress bar with clickable completed steps *@

<nav aria-label="Application progress" class="mb-4">
    <ol class="d-flex list-unstyled justify-content-between step-indicator">
        @for (int i = 0; i < StepNames.Count; i++)
        {
            var step = i;
            var isCompleted = CompletedSteps.Contains(step);
            var isCurrent = step == CurrentStep;
            var isFuture = !isCompleted && !isCurrent;

            <li class="text-center flex-fill position-relative
                        @(isCurrent ? "step-current" : "")
                        @(isCompleted ? "step-completed" : "")
                        @(isFuture ? "step-future" : "")">
                @if (isCompleted)
                {
                    <button type="button"
                            class="btn btn-link text-decoration-none p-0 w-100"
                            @onclick="() => OnStepClicked.InvokeAsync(step)">
                        <span class="step-circle bg-success text-white">✓</span>
                        <span class="d-block small mt-1 text-success fw-semibold">@StepNames[step]</span>
                    </button>
                }
                else
                {
                    <div>
                        <span class="step-circle @(isCurrent ? "bg-primary text-white" : "bg-secondary text-white opacity-50")">
                            @(step + 1)
                        </span>
                        <span class="d-block small mt-1 @(isCurrent ? "text-primary fw-semibold" : "text-muted")">
                            @StepNames[step]
                        </span>
                    </div>
                }
            </li>
        }
    </ol>
</nav>

<style>
    .step-indicator .step-circle {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 2.2rem;
        height: 2.2rem;
        border-radius: 50%;
        font-weight: bold;
        font-size: 0.9rem;
    }
</style>

@code {
    [Parameter, EditorRequired]
    public int CurrentStep { get; set; }

    [Parameter, EditorRequired]
    public HashSet<int> CompletedSteps { get; set; } = new();

    [Parameter, EditorRequired]
    public EventCallback<int> OnStepClicked { get; set; }

    private static readonly List<string> StepNames = new()
    {
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    };
}
"}

